import { Button } from "@/components/ui/button";
import { Dialog, DialogContent, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { offerDaysRemaining } from "@/lib/offerExpiry";
import { trpc } from "@/lib/trpc";
import { categoryMeta, formatSyp, toLegacySyp, toNewSyp, type LahzaCategory } from "@shared/lahza";
import { ArrowRight, BadgePercent, FileText, Image as ImageIcon, ImagePlus, Loader2, LogOut, PackagePlus, Pencil, Plus, Store, Trash2, X } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { useLocation } from "wouter";

const lahzaWordmarkUrl = "/assets/lahza-logo.svg";
const readImageFile = (file: File) => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result ?? "")); reader.onerror = () => reject(new Error("تعذر قراءة الصورة")); reader.readAsDataURL(file); });

type AssignedStore = { id: number; name: string; category: LahzaCategory; categoryTitle?: string | null; imageUrl?: string | null; active: boolean };
type PartnerData = { id: number; name: string; imageUrl?: string | null; storeOpen: boolean; preparationMinutes: number; stores: AssignedStore[] };
type PartnerProduct = { id: number; storeId: number | null; name: string; unit: "وحدة" | "جرام" | "ليتر" | "قنينة" | "طلب"; unitPrice: number; available: boolean; imageUrl?: string | null };
type PartnerOffer = { id: number; storeId: number | null; catalogItemId: number | null; text: string; discountPercent: number; offerPrice: number; imageUrl: string | null; imageStorageKey: string | null; durationDays: number | null; expiresAt: Date | string | null; deletedAt: Date | string | null; active: boolean; featuredStatus: "none" | "pending" | "approved" | "rejected"; featuredReviewNote: string | null };
type WorkReport = { periodStart: Date | string; periodEnd: Date | string; stores: { id: number; name: string }[]; current: { orders: number; completed: number; cancelled: number; sales: number; topProducts: { name: string; quantity: number }[] }; previous: { orders: number; completed: number; cancelled: number; sales: number; topProducts: { name: string; quantity: number }[] }; visits: number; qrVisits: number; directVisits: number };
type StoreTab = "products" | "offers" | "featured" | "report";
type ProductMode = "list" | "create" | "edit";

export default function PartnerPortal() {
  const [, setLocation] = useLocation();
  const utils = trpc.useUtils();
  const sessionQuery = trpc.lahza.partner.session.useQuery();
  const [password, setPassword] = useState("");
  const login = trpc.lahza.partner.login.useMutation({ onSuccess: async result => { await utils.lahza.partner.session.invalidate(); toast.success(`أهلاً بك في متجر ${result.name}`); setLocation("/partner/store"); }, onError: error => toast.error(error.message) });
  const logout = trpc.lahza.partner.logout.useMutation({ onSuccess: () => { utils.lahza.partner.session.setData(undefined, null); setLocation("/"); }, onError: error => toast.error(error.message) });

  if (sessionQuery.isLoading) return <Loading text="جارٍ فتح لوحة الشريك..." />;
  if (!sessionQuery.data) return <main dir="rtl" className="min-h-screen bg-slate-50 px-4 py-10"><section className="mx-auto max-w-md rounded-[2rem] border border-slate-200 bg-white p-6 shadow-lg"><div className="grid h-12 w-12 place-items-center rounded-2xl bg-[#4a2618] text-white"><Store className="h-6 w-6" /></div><div className="mt-5 h-10 w-40 overflow-hidden rounded-xl bg-white"><img src={lahzaWordmarkUrl} alt="لحظة" className="h-10 w-full object-contain" /></div><p className="mt-2 text-sm font-bold text-red-600">بوابة الشركاء</p><h1 className="mt-1 text-2xl font-black text-[#4a2618]">دخول المتجر</h1><p className="mt-2 text-sm leading-7 text-slate-500">استخدم كلمة المرور التي أنشأها لك المالك. رقم الهاتف محفوظ للتواصل وإدارة الحساب.</p><div className="mt-6 space-y-4"><div><Label>كلمة مرور الشريك</Label><Input dir="ltr" type="password" value={password} onChange={event => setPassword(event.target.value)} onKeyDown={event => { if (event.key === "Enter" && password) login.mutate({ password }); }} /></div><Button disabled={login.isPending || !password} onClick={() => login.mutate({ password })} className="h-11 w-full rounded-2xl bg-[#4a2618] hover:bg-[#63301b]">{login.isPending ? "جارٍ الدخول..." : "فتح لوحة المتجر"}</Button><Button variant="ghost" onClick={() => setLocation("/")} className="w-full rounded-xl text-slate-500"><ArrowRight className="h-4 w-4" /> العودة إلى لحظة</Button></div></section></main>;
  return <PartnerDashboardEnhanced partner={sessionQuery.data} onLogout={() => logout.mutate()} onHome={() => setLocation("/")} />;
}

function PartnerDashboardEnhanced({ partner, onLogout, onHome }: { partner: PartnerData; onLogout: () => void; onHome: () => void }) {
  const utils = trpc.useUtils();
  const storesQuery = trpc.lahza.partner.stores.list.useQuery();
  const productsQuery = trpc.lahza.partner.catalog.list.useQuery();
  const offersQuery = trpc.lahza.partner.offers.list.useQuery();
  const [tab, setTab] = useState<StoreTab>("products");
  const reportQuery = trpc.lahza.partner.report.useQuery(undefined, { enabled: tab === "report", retry: false });
  const [selectedStoreId, setSelectedStoreId] = useState("");
  const [productMode, setProductMode] = useState<ProductMode>("list");
  const [editingProduct, setEditingProduct] = useState<PartnerProduct | null>(null);
  const [storeOpen, setStoreOpen] = useState(partner.storeOpen);
  const [preparationMinutes, setPreparationMinutes] = useState(String(partner.preparationMinutes));
  const [partnerImage, setPartnerImage] = useState(partner.imageUrl ?? "");
  const [preview, setPreview] = useState<{ src: string; alt: string } | null>(null);
  const stores = storesQuery.data ?? partner.stores;
  const selectedStore = stores.find(store => String(store.id) === selectedStoreId) ?? stores[0] ?? null;
  const customerStoreImage = partnerImage || selectedStore?.imageUrl || null;
  useEffect(() => {
    setStoreOpen(partner.storeOpen);
    setPreparationMinutes(String(partner.preparationMinutes));
    setPartnerImage(partner.imageUrl ?? "");
  }, [partner.storeOpen, partner.preparationMinutes, partner.imageUrl]);
  const products = selectedStore ? ((productsQuery.data ?? []) as PartnerProduct[]).filter(product => product.storeId === selectedStore.id) : [];
  const offers = selectedStore ? ((offersQuery.data ?? []) as PartnerOffer[]).filter(offer => offer.storeId === selectedStore.id) : [];
  const refreshProducts = () => { utils.lahza.partner.catalog.list.invalidate(); utils.lahza.storefront.products.invalidate(); };
  const refreshOffers = () => { utils.lahza.partner.offers.list.invalidate(); utils.lahza.intercity.offers.invalidate(); };
  const updateAccount = trpc.lahza.partner.store.update.useMutation({ onSuccess: () => { utils.lahza.partner.session.invalidate(); toast.success("تم حفظ بيانات الحساب والصورة"); }, onError: error => toast.error(error.message) });
  const uploadPartnerImage = trpc.lahza.partner.store.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const toggleStoreOpen = () => {
    const nextStoreOpen = !storeOpen;
    setStoreOpen(nextStoreOpen);
    updateAccount.mutate({ storeOpen: nextStoreOpen, preparationMinutes: Number(preparationMinutes), imageUrl: partnerImage || undefined }, { onError: () => setStoreOpen(storeOpen) });
  };
  const saveAccount = async () => { const uploaded = partnerImage.startsWith("data:") ? await uploadPartnerImage.mutateAsync({ dataUrl: partnerImage }) : null; updateAccount.mutate({ storeOpen, preparationMinutes: Number(preparationMinutes), imageUrl: uploaded?.imageUrl ?? partnerImage }); };
  const createProduct = trpc.lahza.partner.catalog.create.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تمت إضافة المنتج"); }, onError: error => toast.error(error.message) });
  const updateProduct = trpc.lahza.partner.catalog.update.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تم تحديث المنتج"); }, onError: error => toast.error(error.message) });
  const removeProduct = trpc.lahza.partner.catalog.remove.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تم حذف المنتج"); }, onError: error => toast.error(error.message) });
  const uploadProductImage = trpc.lahza.partner.catalog.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const createOffer = trpc.lahza.partner.offers.create.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تمت إضافة العرض إلى متجرك"); }, onError: error => toast.error(error.message) });
  const updateOffer = trpc.lahza.partner.offers.update.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تم حفظ تعديل العرض؛ يلزم طلب تمييزه من جديد إن أردت ظهوره بالواجهة"); }, onError: error => toast.error(error.message) });
  const removeOffer = trpc.lahza.partner.offers.remove.useMutation({ onSuccess: () => { refreshOffers(); toast.success("أُخفي العرض من متجر العملاء"); }, onError: error => toast.error(error.message) });
  const uploadOfferImage = trpc.lahza.partner.offers.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const requestFeaturedOffer = trpc.lahza.partner.offers.requestFeatured.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تم إرسال العرض المميز للمالك للمراجعة"); }, onError: error => toast.error(error.message) });
  const uploadProduct = async (dataUrl: string | undefined) => !dataUrl || !selectedStore ? "" : (await uploadProductImage.mutateAsync({ storeId: selectedStore.id, dataUrl })).imageUrl;
  const saveNewProduct = async (input: ProductDraft) => { if (!selectedStore) return; const imageUrl = await uploadProduct(input.dataUrl); await createProduct.mutateAsync({ name: input.name, category: selectedStore.category, storeId: selectedStore.id, unit: "وحدة", price: input.price, available: true, imageUrl }); setProductMode("list"); };
  const saveEditedProduct = async (input: ProductDraft) => { if (!selectedStore || !editingProduct) return; const imageUrl = input.dataUrl ? await uploadProduct(input.dataUrl) : editingProduct.imageUrl ?? ""; await updateProduct.mutateAsync({ id: editingProduct.id, name: input.name, category: selectedStore.category, storeId: selectedStore.id, unit: editingProduct.unit, price: input.price, available: editingProduct.available, imageUrl }); setEditingProduct(null); setProductMode("list"); };
  const addOffer = async (input: { catalogItemId: number; text: string; durationDays: number; offerPrice: number; dataUrl?: string }) => { if (!selectedStore) return 0; const image = input.dataUrl ? await uploadOfferImage.mutateAsync({ storeId: selectedStore.id, dataUrl: input.dataUrl }) : null; const created = await createOffer.mutateAsync({ storeId: selectedStore.id, catalogItemId: input.catalogItemId, text: input.text, durationDays: input.durationDays, offerPrice: input.offerPrice, imageUrl: image?.imageUrl ?? "", imageStorageKey: image?.imageStorageKey ?? "", active: true }); return created.id; };
  const storeCategoryTitle = (store: AssignedStore) => store.categoryTitle ?? categoryMeta[store.category].title;
  if (storesQuery.isLoading) return <Loading text="جارٍ تحميل المتجر..." />;
  if (!stores.length || !selectedStore) return <main dir="rtl" className="min-h-screen bg-slate-50 px-4 py-8"><EmptyStores /></main>;
  return <main dir="rtl" className="min-h-screen bg-slate-50 text-slate-950"><header className="border-b border-slate-200 bg-white"><div className="mx-auto flex w-full max-w-5xl items-center justify-between gap-4 px-4 py-4"><div><p className="text-xs font-bold text-red-600">لحظة للشركاء</p><div className="mt-1 h-8 w-40"><img src={lahzaWordmarkUrl} alt="لحظة" className="h-full w-full object-contain" /></div></div><div className="flex items-center gap-2"><Button variant="outline" onClick={onHome} className="rounded-xl border-rose-200 bg-rose-50 text-[#63301b]"><ArrowRight className="h-4 w-4" /> الصفحة الرئيسية</Button><Button variant="outline" onClick={onLogout} className="rounded-xl text-slate-600"><LogOut className="h-4 w-4" /> خروج</Button></div></div></header><section className="mx-auto grid w-full max-w-5xl gap-5 px-4 py-7"><section className="rounded-3xl border border-rose-100 bg-rose-50 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-bold text-[#63301b]">حالة حساب الشريك</p><p className="mt-1 text-xs text-slate-500">عند الإغلاق تتوقف الطلبات الجديدة من متجرك.</p></div><button onClick={toggleStoreOpen} disabled={updateAccount.isPending} className={`rounded-full px-4 py-2 text-sm font-bold ${storeOpen ? "bg-emerald-600 text-white" : "bg-slate-400 text-white"}`}>{storeOpen ? "الحساب مفتوح" : "الحساب مغلق"}</button></div><div className="mt-4 flex flex-wrap items-end gap-3"><div><Label>وقت التجهيز بالدقائق</Label><Input inputMode="numeric" value={preparationMinutes} onChange={event => setPreparationMinutes(event.target.value.replace(/\D/g, ""))} className="mt-1 w-48 bg-white" /></div><div><Label>صورة المتجر الظاهرة للزبائن</Label><label className="mt-1 inline-flex cursor-pointer items-center gap-2 rounded-xl border border-orange-200 bg-white px-3 py-2 text-xs font-bold text-[#63301b]"><ImagePlus className="h-4 w-4" /> رفع صورة<input type="file" accept="image/png,image/jpeg,image/webp" className="sr-only" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; try { setPartnerImage(await readImageFile(file)); } catch { toast.error("تعذر قراءة الصورة"); } }} /></label>{partnerImage ? <img src={partnerImage} alt="صورة المتجر" className="mt-1 h-10 w-10 rounded-lg object-cover" /> : null}</div><Button disabled={updateAccount.isPending || uploadPartnerImage.isPending || !preparationMinutes} onClick={saveAccount} className="rounded-xl bg-[#4a2618] hover:bg-[#63301b]">حفظ</Button></div></section><section className="overflow-hidden rounded-3xl bg-gradient-to-l from-[#4a2618] via-[#63301b] to-red-600 p-6 text-white shadow-lg"><div className="overflow-hidden rounded-3xl border border-white/20 bg-white/10 shadow-xl"><div className="relative h-48 w-full bg-black/15">{customerStoreImage ? <img src={customerStoreImage} alt={`صورة متجر ${selectedStore.name}`} className="h-full w-full object-cover" /> : <div className="grid h-full place-items-center"><Store className="h-16 w-16 text-white/80" /></div>}<div className="absolute inset-x-0 bottom-0 bg-gradient-to-t from-black/70 to-transparent px-5 pb-4 pt-12"><p className="text-sm font-bold text-rose-100">لوحة إدارة المتجر</p><h1 className="mt-1 text-3xl font-black">{selectedStore.name}</h1><p className="mt-2 text-sm text-white/85">{storeCategoryTitle(selectedStore)} · كما يظهر للزبائن</p></div></div><div className="flex items-center justify-between gap-3 px-5 py-3"><span className="text-sm font-bold text-white/85">صورة المتجر الحالية</span><Store className="h-7 w-7 text-white/90" /></div></div>{stores.length > 1 ? <div className="mt-5 max-w-sm"><Label className="text-white">اختيار متجر</Label><select value={selectedStore.id} onChange={event => { setSelectedStoreId(event.target.value); setProductMode("list"); setEditingProduct(null); setTab("products"); }} className="form-select mt-1 border-white/30 bg-white text-[#4a2618]">{stores.map(store => <option key={store.id} value={store.id}>{store.name} — {storeCategoryTitle(store)}</option>)}</select></div> : null}</section><section className="rounded-3xl border border-slate-200 bg-white p-3"><div className="grid grid-cols-2 gap-2"><TabButton active={tab === "products"} onClick={() => { setTab("products"); setProductMode("list"); }} icon={<PackagePlus className="h-4 w-4" />}>المنتجات</TabButton><TabButton active={tab === "featured"} onClick={() => setTab("featured")} icon={<BadgePercent className="h-4 w-4" />}>العروض المميزة</TabButton></div></section>{tab === "products" ? <ProductsPanel store={selectedStore} products={products} mode={productMode} editingProduct={editingProduct} saving={createProduct.isPending || updateProduct.isPending || removeProduct.isPending || uploadProductImage.isPending} onNew={() => { setEditingProduct(null); setProductMode("create"); }} onCancel={() => { setEditingProduct(null); setProductMode("list"); }} onEdit={product => { setEditingProduct(product); setProductMode("edit"); }} onCreate={saveNewProduct} onUpdate={saveEditedProduct} onToggle={product => updateProduct.mutate({ id: product.id, name: product.name, category: selectedStore.category, storeId: selectedStore.id, unit: product.unit, price: toNewSyp(product.unitPrice), available: !product.available, imageUrl: product.imageUrl ?? "" })} onRemove={product => { if (confirm(`حذف ${product.name}؟`)) removeProduct.mutate({ id: product.id }); }} onPreview={(src, alt) => setPreview({ src, alt })} /> : <><OffersPanel featuredOnly offers={offers} products={products} store={selectedStore} creating={createOffer.isPending || uploadOfferImage.isPending || requestFeaturedOffer.isPending} saving={updateOffer.isPending} deleting={removeOffer.isPending} onCreate={async input => { const id = await addOffer(input); await requestFeaturedOffer.mutateAsync({ id, storeId: selectedStore.id }); refreshOffers(); toast.success("تم إنشاء العرض المميز وإرساله للمالك للمراجعة"); }} onUpdate={input => updateOffer.mutate(input)} onRemove={id => { if (confirm("حذف هذا العرض؟")) removeOffer.mutate({ id, storeId: selectedStore.id }); }} onPreview={(src, alt) => setPreview({ src, alt })} /><FeaturedOffersPanel offers={offers} submitting={requestFeaturedOffer.isPending} onRequest={offer => requestFeaturedOffer.mutate({ id: offer.id, storeId: selectedStore.id })} /></>}</section><ImagePreview preview={preview} onClose={() => setPreview(null)} /></main>;
}

function PartnerDashboard({ partner, onLogout, onHome }: { partner: PartnerData; onLogout: () => void; onHome: () => void }) {
  const utils = trpc.useUtils();
  const storesQuery = trpc.lahza.partner.stores.list.useQuery();
  const productsQuery = trpc.lahza.partner.catalog.list.useQuery();
  const offersQuery = trpc.lahza.partner.offers.list.useQuery();
  const [tab, setTab] = useState<StoreTab>("products");
  const reportQuery = trpc.lahza.partner.report.useQuery(undefined, { enabled: tab === "report", retry: false });
  const [selectedStoreId, setSelectedStoreId] = useState("");
  const [productMode, setProductMode] = useState<ProductMode>("list");
  const [editingProduct, setEditingProduct] = useState<PartnerProduct | null>(null);
  const [storeOpen, setStoredStoreOpen] = useState(partner.storeOpen);
  const [preparationMinutes, setPreparationMinutes] = useState(String(partner.preparationMinutes));
  const [partnerImage, setPartnerImage] = useState(partner.imageUrl ?? "");
  const [preview, setPreview] = useState<{ src: string; alt: string } | null>(null);
  const stores = storesQuery.data ?? partner.stores;
  const selectedStore = stores.find(store => String(store.id) === selectedStoreId) ?? stores[0] ?? null;
  const customerStoreImage = partnerImage || selectedStore?.imageUrl || null;
  useEffect(() => {
    setStoreOpen(partner.storeOpen);
    setPreparationMinutes(String(partner.preparationMinutes));
    setPartnerImage(partner.imageUrl ?? "");
  }, [partner.storeOpen, partner.preparationMinutes, partner.imageUrl]);
  const products = selectedStore ? ((productsQuery.data ?? []) as PartnerProduct[]).filter(product => product.storeId === selectedStore.id) : [];
  const offers = selectedStore ? ((offersQuery.data ?? []) as PartnerOffer[]).filter(offer => offer.storeId === selectedStore.id) : [];
  const refreshProducts = () => { utils.lahza.partner.catalog.list.invalidate(); utils.lahza.storefront.products.invalidate(); };
  const refreshOffers = () => { utils.lahza.partner.offers.list.invalidate(); utils.lahza.intercity.offers.invalidate(); };
  const updateAccount = trpc.lahza.partner.store.update.useMutation({ onSuccess: () => { utils.lahza.partner.session.invalidate(); toast.success("تم حفظ بيانات الحساب والصورة"); }, onError: error => toast.error(error.message) });
  const uploadPartnerImage = trpc.lahza.partner.store.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const saveAccount = async () => { const uploaded = partnerImage.startsWith("data:") ? await uploadPartnerImage.mutateAsync({ dataUrl: partnerImage }) : null; updateAccount.mutate({ storeOpen, preparationMinutes: Number(preparationMinutes), imageUrl: uploaded?.imageUrl ?? partnerImage }); };
  const setStoreOpen = (value: boolean | ((current: boolean) => boolean)) => {
    if (!preparationMinutes) {
      toast.error("أدخل وقت التجهيز أولاً ثم غيّر حالة المتجر");
      return;
    }
    const previousStoreOpen = storeOpen;
    const nextStoreOpen = typeof value === "function" ? value(storeOpen) : value;
    setStoredStoreOpen(nextStoreOpen);
    updateAccount.mutate({ storeOpen: nextStoreOpen, preparationMinutes: Number(preparationMinutes) }, { onError: () => setStoredStoreOpen(previousStoreOpen) });
  };
  const createProduct = trpc.lahza.partner.catalog.create.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تمت إضافة المنتج"); }, onError: error => toast.error(error.message) });
  const updateProduct = trpc.lahza.partner.catalog.update.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تم تحديث المنتج"); }, onError: error => toast.error(error.message) });
  const removeProduct = trpc.lahza.partner.catalog.remove.useMutation({ onSuccess: () => { refreshProducts(); toast.success("تم حذف المنتج"); }, onError: error => toast.error(error.message) });
  const uploadProductImage = trpc.lahza.partner.catalog.uploadImage.useMutation({ onError: error => toast.error(error.message) });
  const createOffer = trpc.lahza.partner.offers.create.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تمت إضافة العرض وربطه بصنف المتجر"); }, onError: error => toast.error(error.message) });
  const updateOffer = trpc.lahza.partner.offers.update.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تم حفظ تعديل العرض والصنف المرتبط"); }, onError: error => toast.error(error.message) });
  const removeOffer = trpc.lahza.partner.offers.remove.useMutation({ onSuccess: () => { refreshOffers(); toast.success("أُخفي العرض من واجهة العملاء"); }, onError: error => toast.error(error.message) });
  const requestFeaturedOffer = trpc.lahza.partner.offers.requestFeatured.useMutation({ onSuccess: () => { refreshOffers(); toast.success("تم إرسال طلب العرض المميز إلى المالك للمراجعة"); }, onError: error => toast.error(error.message) });
  const uploadOfferImage = trpc.lahza.partner.offers.uploadImage.useMutation({ onError: error => toast.error(error.message) });

  const uploadProduct = async (dataUrl: string | undefined) => !dataUrl || !selectedStore ? "" : (await uploadProductImage.mutateAsync({ storeId: selectedStore.id, dataUrl })).imageUrl;
  const saveNewProduct = async (input: ProductDraft) => {
    if (!selectedStore) return;
    const imageUrl = await uploadProduct(input.dataUrl);
    await createProduct.mutateAsync({ name: input.name, category: selectedStore.category, storeId: selectedStore.id, unit: "وحدة", price: input.price, available: true, imageUrl });
    setProductMode("list");
  };
  const saveEditedProduct = async (input: ProductDraft) => {
    if (!selectedStore || !editingProduct) return;
    const imageUrl = input.dataUrl ? await uploadProduct(input.dataUrl) : editingProduct.imageUrl ?? "";
    await updateProduct.mutateAsync({ id: editingProduct.id, name: input.name, category: selectedStore.category, storeId: selectedStore.id, unit: editingProduct.unit, price: input.price, available: editingProduct.available, imageUrl });
    setEditingProduct(null);
    setProductMode("list");
  };
  const addOffer = async (input: { catalogItemId: number; text: string; durationDays: number; offerPrice: number; dataUrl?: string }) => {
    if (!selectedStore) return;
    const image = input.dataUrl ? await uploadOfferImage.mutateAsync({ storeId: selectedStore.id, dataUrl: input.dataUrl }) : null;
    await createOffer.mutateAsync({ storeId: selectedStore.id, catalogItemId: input.catalogItemId, text: input.text, durationDays: input.durationDays, offerPrice: input.offerPrice, imageUrl: image?.imageUrl ?? "", imageStorageKey: image?.imageStorageKey ?? "", active: true });
  };

  const storeCategoryTitle = (store: AssignedStore) => store.categoryTitle ?? categoryMeta[store.category].title;
  return <main dir="rtl" className="min-h-screen bg-slate-50 text-slate-950"><header className="border-b border-slate-200 bg-white"><div className="mx-auto flex w-full max-w-5xl items-center justify-between gap-4 px-4 py-4"><div><p className="text-xs font-bold text-red-600">لحظة للشركاء</p><div className="mt-1 h-8 w-40"><img src={lahzaWordmarkUrl} alt="لحظة" className="h-full w-full object-contain" /></div></div><div className="flex items-center gap-2"><Button variant="outline" onClick={onHome} className="rounded-xl border-rose-200 bg-rose-50 text-[#63301b]"><ArrowRight className="h-4 w-4" /> الصفحة الرئيسية</Button><Button variant="outline" onClick={onLogout} className="rounded-xl text-slate-600"><LogOut className="h-4 w-4" /> خروج</Button></div></div></header><section className="mx-auto grid w-full max-w-5xl gap-5 px-4 py-7"><section className="rounded-3xl border border-rose-100 bg-rose-50 p-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="text-sm font-bold text-[#63301b]">حالة حساب الشريك</p><p className="mt-1 text-xs text-slate-500">عند الإغلاق تتوقف الطلبات الجديدة من متجرك.</p></div><button onClick={() => setStoreOpen(value => !value)} className={`rounded-full px-4 py-2 text-sm font-bold ${storeOpen ? "bg-emerald-600 text-white" : "bg-slate-400 text-white"}`}>{storeOpen ? "الحساب مفتوح" : "الحساب مغلق"}</button></div><div className="mt-4 flex flex-wrap items-end gap-3"><div><Label>وقت التجهيز بالدقائق</Label><Input inputMode="numeric" value={preparationMinutes} onChange={event => setPreparationMinutes(event.target.value.replace(/\D/g, ""))} className="mt-1 w-48 bg-white" /></div><div><Label>صورة المتجر الظاهرة للزبائن</Label><label className="mt-1 inline-flex cursor-pointer items-center gap-2 rounded-xl border border-orange-200 bg-white px-3 py-2 text-xs font-bold text-[#63301b]"><ImagePlus className="h-4 w-4" /> رفع صورة<input type="file" accept="image/png,image/jpeg,image/webp" className="sr-only" onChange={async event => { const file = event.target.files?.[0]; if (!file) return; try { setPartnerImage(await readImageFile(file)); } catch { toast.error("تعذر قراءة الصورة"); } }} /></label>{partnerImage ? <img src={partnerImage} alt="صورة المتجر" className="mt-1 h-10 w-10 rounded-lg object-cover" /> : null}</div><Button disabled={updateAccount.isPending || uploadPartnerImage.isPending || !preparationMinutes} onClick={saveAccount} className="rounded-xl bg-[#4a2618] hover:bg-[#63301b]">حفظ</Button></div></section>{storesQuery.isLoading ? <Loading text="جارٍ تحميل المتجر..." /> : !stores.length ? <EmptyStores /> : selectedStore ? <><section className="overflow-hidden rounded-3xl bg-gradient-to-l from-[#4a2618] via-[#63301b] to-red-600 p-6 text-white shadow-lg"><div className="flex flex-wrap items-center justify-between gap-4"><div><p className="text-sm font-bold text-rose-100">لوحة إدارة المتجر</p><h1 className="mt-1 text-3xl font-black">{selectedStore.name}</h1><p className="mt-2 text-sm text-white/80">{storeCategoryTitle(selectedStore)} · إدارة المنتجات والعروض من مكان واحد</p></div><Store className="h-12 w-12 text-white/90" /></div>{stores.length > 1 ? <div className="mt-5 max-w-sm"><Label className="text-white">اختيار متجر</Label><select value={selectedStore.id} onChange={event => { setSelectedStoreId(event.target.value); setProductMode("list"); setEditingProduct(null); }} className="form-select mt-1 border-white/30 bg-white text-[#4a2618]">{stores.map(store => <option key={store.id} value={store.id}>{store.name} — {storeCategoryTitle(store)}</option>)}</select></div> : null}</section><section className="rounded-3xl border border-slate-200 bg-white p-3"><div className="grid grid-cols-3 gap-2"><TabButton active={tab === "products"} onClick={() => { setTab("products"); setProductMode("list"); }} icon={<PackagePlus className="h-4 w-4" />}>المنتجات</TabButton><TabButton active={tab === "offers"} onClick={() => setTab("offers")} danger icon={<BadgePercent className="h-4 w-4" />}>العروض</TabButton><TabButton active={tab === "report"} onClick={() => setTab("report")} icon={<FileText className="h-4 w-4" />}>تقرير العمل</TabButton></div></section>{tab === "products" ? <ProductsPanel store={selectedStore} products={products} mode={productMode} editingProduct={editingProduct} saving={createProduct.isPending || updateProduct.isPending || removeProduct.isPending || uploadProductImage.isPending} onNew={() => { setEditingProduct(null); setProductMode("create"); }} onCancel={() => { setEditingProduct(null); setProductMode("list"); }} onEdit={product => { setEditingProduct(product); setProductMode("edit"); }} onCreate={saveNewProduct} onUpdate={saveEditedProduct} onToggle={product => updateProduct.mutate({ id: product.id, name: product.name, category: selectedStore.category, storeId: selectedStore.id, unit: product.unit, price: toNewSyp(product.unitPrice), available: !product.available, imageUrl: product.imageUrl ?? "" })} onRemove={product => { if (confirm(`حذف ${product.name}؟`)) removeProduct.mutate({ id: product.id }); }} onPreview={(src, alt) => setPreview({ src, alt })} /> : tab === "offers" ? <OffersPanel offers={offers} products={products} store={selectedStore} creating={createOffer.isPending || uploadOfferImage.isPending} saving={updateOffer.isPending} deleting={removeOffer.isPending} onCreate={addOffer} onUpdate={input => updateOffer.mutate(input)} onRemove={id => { if (confirm("حذف هذا العرض؟")) removeOffer.mutate({ id, storeId: selectedStore.id }); }} onPreview={(src, alt) => setPreview({ src, alt })} /> : <WorkReportPanel report={reportQuery.data as WorkReport | undefined} loading={reportQuery.isLoading} error={reportQuery.error?.message} />}</> : null}</section><ImagePreview preview={preview} onClose={() => setPreview(null)} /></main>;
}

type ProductDraft = { name: string; price: number; dataUrl?: string };

function ProductsPanel({ store, products, mode, editingProduct, saving, onNew, onCancel, onEdit, onCreate, onUpdate, onToggle, onRemove, onPreview }: { store: AssignedStore; products: PartnerProduct[]; mode: ProductMode; editingProduct: PartnerProduct | null; saving: boolean; onNew: () => void; onCancel: () => void; onEdit: (product: PartnerProduct) => void; onCreate: (input: ProductDraft) => Promise<void>; onUpdate: (input: ProductDraft) => Promise<void>; onToggle: (product: PartnerProduct) => void; onRemove: (product: PartnerProduct) => void; onPreview: (src: string, alt: string) => void }) {
  return <section className="space-y-5">{mode === "list" ? <><div className="flex flex-wrap items-center justify-between gap-3 rounded-3xl border border-slate-200 bg-white p-5"><div><h2 className="text-lg font-black text-[#4a2618]">منتجات {store.name}</h2><p className="mt-1 text-sm text-slate-500">اضغط تعديل منتج لتغيير بياناته أو حالته.</p></div><Button onClick={onNew} className="rounded-xl bg-red-600 hover:bg-red-700"><Plus className="h-4 w-4" /> إضافة منتج جديد</Button></div>{products.length ? <div className="grid gap-3 sm:grid-cols-2">{products.map(product => <article key={product.id} className="rounded-2xl border border-slate-200 bg-white p-3 shadow-sm"><ImageThumbnail src={product.imageUrl} alt={`صورة ${product.name}`} onPreview={onPreview} /><div className="mt-3 min-w-0"><strong className="block truncate text-base text-[#4a2618]">{product.name}</strong><span className="mt-1 block text-xs text-slate-500">{formatSyp(product.unitPrice)} · {product.available ? "متاح" : "موقوف"}</span><Button size="sm" variant="outline" onClick={() => onEdit(product)} className="mt-3 rounded-lg border-rose-100 bg-rose-50 text-[#63301b]"><Pencil className="h-3.5 w-3.5" /> تعديل منتج</Button></div></article>)}</div> : <div className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><PackagePlus className="mx-auto h-8 w-8 text-slate-400" /><strong className="mt-3 block text-[#4a2618]">لا توجد منتجات بعد</strong><p className="mt-2 text-sm text-slate-500">ابدأ بإضافة أول منتج إلى متجر {store.name}.</p><Button onClick={onNew} className="mt-4 rounded-xl bg-red-600 hover:bg-red-700"><Plus className="h-4 w-4" /> إضافة منتج جديد</Button></div>}</> : <ProductForm title={mode === "create" ? "إضافة منتج جديد" : `تعديل ${editingProduct?.name ?? "المنتج"}`} product={mode === "edit" ? editingProduct : null} saving={saving} onCancel={onCancel} onSave={mode === "create" ? onCreate : onUpdate} onToggle={mode === "edit" && editingProduct ? () => onToggle(editingProduct) : undefined} onRemove={mode === "edit" && editingProduct ? () => onRemove(editingProduct) : undefined} onPreview={onPreview} />}</section>;
}

function ProductForm({ title, product, saving, onCancel, onSave, onToggle, onRemove, onPreview }: { title: string; product: PartnerProduct | null; saving: boolean; onCancel: () => void; onSave: (input: ProductDraft) => Promise<void>; onToggle?: () => void; onRemove?: () => void; onPreview: (src: string, alt: string) => void }) {
  const [name, setName] = useState(product?.name ?? "");
  const [price, setPrice] = useState(product ? String(toNewSyp(product.unitPrice)) : "");
  const [dataUrl, setDataUrl] = useState("");
  const chooseImage = (file?: File) => { if (!file) return; if (!/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 5 * 1024 * 1024) { toast.error("اختر صورة PNG أو JPG أو WEBP بحجم لا يتجاوز 5 ميغابايت"); return; } const reader = new FileReader(); reader.onload = () => setDataUrl(String(reader.result ?? "")); reader.readAsDataURL(file); };
  const imageSrc = dataUrl || product?.imageUrl || "";
  return <section className="rounded-3xl border border-slate-200 bg-white p-5"><div className="flex items-center justify-between gap-3"><div><p className="text-xs font-bold text-red-600">إدارة المنتجات</p><h2 className="mt-1 text-xl font-black text-[#4a2618]">{title}</h2></div><Button variant="ghost" onClick={onCancel} className="rounded-xl text-slate-500"><X className="h-4 w-4" /> إغلاق</Button></div><div className="mt-5 grid gap-4 md:grid-cols-2"><div><Label>اسم المنتج</Label><Input value={name} onChange={event => setName(event.target.value)} className="mt-1" /></div><div><Label>السعر (ل.س)</Label><Input inputMode="numeric" value={price} onChange={event => setPrice(event.target.value.replace(/\D/g, ""))} className="mt-1" /></div></div><div className="mt-4 rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-3"><Label className="flex items-center gap-2"><ImageIcon className="h-4 w-4 text-red-600" /> صورة المنتج <span className="text-slate-400">(اختيارية)</span></Label><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-bold text-[#4a2618]"><ImagePlus className="h-4 w-4" /> اختيار صورة<input type="file" className="sr-only" accept="image/png,image/jpeg,image/webp" onChange={event => chooseImage(event.target.files?.[0])} /></label>{imageSrc ? <><ImageThumbnail src={imageSrc} alt={`صورة ${name || "المنتج"}`} onPreview={onPreview} /><button type="button" onClick={() => setDataUrl("")} className="text-xs font-bold text-red-600">إلغاء الصورة الجديدة</button></> : null}</div></div><div className="mt-5 flex flex-wrap gap-2"><Button disabled={saving || !name.trim() || !price} onClick={() => onSave({ name: name.trim(), price: Number(price), dataUrl: dataUrl || undefined })} className="rounded-xl bg-[#4a2618] hover:bg-[#63301b]">{saving ? "جارٍ الحفظ..." : "حفظ المنتج"}</Button>{onToggle && product ? <Button disabled={saving} variant="outline" onClick={onToggle} className="rounded-xl border-amber-200 bg-amber-50 text-amber-800">{product.available ? "إيقاف المنتج" : "تفعيل المنتج"}</Button> : null}{onRemove ? <Button disabled={saving} variant="outline" onClick={onRemove} className="rounded-xl border-red-100 bg-red-50 text-red-700"><Trash2 className="h-4 w-4" /> حذف المنتج</Button> : null}</div></section>;
}

function OffersPanel({ featuredOnly = false, offers, products, store, creating, saving, deleting, onCreate, onUpdate, onRemove, onPreview }: { featuredOnly?: boolean; offers: PartnerOffer[]; products: PartnerProduct[]; store: AssignedStore; creating: boolean; saving: boolean; deleting: boolean; onCreate: (input: { catalogItemId: number; text: string; durationDays: number; offerPrice: number; dataUrl?: string }) => Promise<void>; onUpdate: (input: { id: number; storeId: number; catalogItemId: number; text: string; imageUrl: string; imageStorageKey: string; durationDays: number; offerPrice: number; active: boolean }) => void; onRemove: (id: number) => void; onPreview: (src: string, alt: string) => void }) {
  const [text, setText] = useState("");
  const [catalogItemId, setCatalogItemId] = useState("");
  const [durationDays, setDurationDays] = useState("30");
  const [offerPrice, setOfferPrice] = useState("");
  const [dataUrl, setDataUrl] = useState("");
  const availableProducts = products.filter(product => product.available);
  const selectedProduct = availableProducts.find(product => String(product.id) === catalogItemId) ?? null;
  const originalPriceNew = selectedProduct ? toNewSyp(selectedProduct.unitPrice) : 0;
  const offerPriceNew = Number(offerPrice);
  const calculatedDiscount = originalPriceNew > 0 && offerPriceNew > 0 ? Math.round((originalPriceNew - offerPriceNew) * 100 / originalPriceNew) : 0;
  const validDuration = Number(durationDays) >= 1 && Number(durationDays) <= 365;
  const validOfferPrice = Number.isInteger(offerPriceNew) && offerPriceNew > 0 && offerPriceNew < originalPriceNew && calculatedDiscount >= 1 && calculatedDiscount <= 90;
  const chooseImage = (file?: File) => {
    if (!file) return;
    if (!/^image\/(png|jpeg|webp)$/.test(file.type) || file.size > 5 * 1024 * 1024) { toast.error("اختر صورة PNG أو JPG أو WEBP بحجم لا يتجاوز 5 ميغابايت"); return; }
    const reader = new FileReader();
    reader.onload = () => setDataUrl(String(reader.result ?? ""));
    reader.readAsDataURL(file);
  };
  return <section className="grid gap-5 lg:grid-cols-2"><section className="rounded-3xl border border-red-100 bg-white p-5"><div className="flex items-center gap-2"><BadgePercent className="h-5 w-5 text-red-600" /><div><h2 className="text-lg font-black text-[#4a2618]">{featuredOnly ? "إنشاء عرض مميز جديد" : "صمّم عرضاً مميزاً"}</h2><p className="mt-1 text-xs leading-6 text-slate-500">اختر المنتج وأدخل سعر العرض الجديد؛ يحسب لحظة نسبة الخصم تلقائياً.</p></div></div><div className="mt-5 space-y-3"><div><Label>عنوان العرض</Label><Textarea value={text} onChange={event => setText(event.target.value)} placeholder="مثال: عرض نهاية الأسبوع على علبة المعمول" /></div><div><Label>صنف العرض</Label><select value={catalogItemId} onChange={event => { setCatalogItemId(event.target.value); setOfferPrice(""); }} className="form-select mt-1"><option value="">اختر صنفاً من منتجات {store.name}</option>{availableProducts.map(product => <option key={product.id} value={product.id}>{product.name} · {formatSyp(product.unitPrice)}</option>)}</select>{!availableProducts.length ? <p className="mt-1 text-xs text-red-600">أضف منتجاً متاحاً إلى المتجر أولاً.</p> : null}</div><div className="grid grid-cols-2 gap-3"><div><Label>سعر العرض الجديد (ل.س)</Label><Input disabled={!selectedProduct} inputMode="numeric" value={offerPrice} onChange={event => setOfferPrice(event.target.value.replace(/\D/g, ""))} placeholder={selectedProduct ? "أدخل سعر العرض" : "اختر المنتج أولاً"} className="mt-1" /><p className="mt-1 text-xs text-slate-500">سعر المنتج: {selectedProduct ? formatSyp(selectedProduct.unitPrice) : "—"}</p></div><div><Label>مدة العرض بالأيام</Label><Input inputMode="numeric" value={durationDays} onChange={event => setDurationDays(event.target.value.replace(/\D/g, ""))} className="mt-1" /><p className="mt-1 text-xs text-slate-500">من يوم إلى 365 يوماً.</p></div></div><div className={`rounded-xl px-3 py-2 text-xs font-bold ${validOfferPrice ? "bg-emerald-50 text-emerald-800" : offerPrice ? "bg-red-50 text-red-700" : "bg-rose-50 text-[#63301b]"}`}>{validOfferPrice ? <>نسبة الخصم المحسوبة: <strong>{calculatedDiscount}%</strong> · سعر العرض صالح</> : offerPrice ? "يجب أن يكون سعر العرض أقل من سعر المنتج وأن يحقق خصماً بين 1% و90%." : "أدخل سعر العرض الجديد ليظهر مقدار الخصم تلقائياً."}</div><div className="rounded-2xl border border-dashed border-slate-200 bg-slate-50 p-3"><Label className="flex items-center gap-2"><ImageIcon className="h-4 w-4 text-red-600" /> صورة إضافية <span className="text-slate-400">(اختيارية)</span></Label><p className="mt-1 text-xs leading-5 text-slate-500">يستخدم القالب صورة المنتج تلقائياً. أضف صورة فقط إذا أردت خلفية أو لقطة إضافية.</p><div className="mt-3 flex flex-wrap items-center gap-3"><label className="inline-flex cursor-pointer items-center gap-2 rounded-xl border border-slate-200 bg-white px-3 py-2.5 text-sm font-bold text-[#4a2618]"><ImagePlus className="h-4 w-4" /> اختيار صورة<input type="file" className="sr-only" accept="image/png,image/jpeg,image/webp" onChange={event => chooseImage(event.target.files?.[0])} /></label>{dataUrl ? <><ImageThumbnail src={dataUrl} alt="صورة إضافية للعرض" onPreview={onPreview} /><button type="button" onClick={() => setDataUrl("")} className="text-xs font-bold text-red-600">إزالة الصورة</button></> : null}</div></div><Button disabled={creating || text.trim().length < 3 || !catalogItemId || !validDuration || !validOfferPrice} onClick={async () => { await onCreate({ catalogItemId: Number(catalogItemId), text: text.trim(), durationDays: Number(durationDays), offerPrice: offerPriceNew, dataUrl: dataUrl || undefined }); setText(""); setCatalogItemId(""); setOfferPrice(""); setDataUrl(""); }} className="w-full rounded-xl bg-red-600 hover:bg-red-700">{creating ? "جارٍ إنشاء العرض..." : featuredOnly ? "إنشاء وإرسال العرض المميز" : "حفظ بطاقة العرض"}</Button></div></section><section className="rounded-3xl border border-rose-100 bg-white p-5"><div className="flex items-center gap-2"><BadgePercent className="h-5 w-5 text-red-600" /><div><h2 className="text-lg font-black text-[#4a2618]">معاينة بطاقة لحظة</h2><p className="mt-1 text-xs text-slate-500">هذه هي البطاقة التي يراجعها المالك قبل النشر.</p></div></div><div className="mt-4"><OfferArtworkPreview product={selectedProduct} storeName={store.name} title={text || "عنوان العرض"} offerPrice={validOfferPrice ? toLegacySyp(offerPriceNew) : undefined} customImage={dataUrl || undefined} /></div></section>{!featuredOnly ? <section className="lg:col-span-2 rounded-3xl border border-slate-200 bg-white p-5"><div className="flex items-center gap-2"><BadgePercent className="h-5 w-5 text-red-600" /><h2 className="text-lg font-black text-[#4a2618]">العروض المضافة</h2></div>{offers.length ? <div className="mt-4 grid gap-3 lg:grid-cols-2">{offers.map(offer => <OfferEditor key={offer.id} offer={offer} products={availableProducts} storeId={store.id} saving={saving} deleting={deleting} onUpdate={onUpdate} onRemove={onRemove} onPreview={onPreview} />)}</div> : <p className="mt-4 rounded-2xl bg-slate-50 p-4 text-sm text-slate-500">لا توجد عروض مضافة في هذا المتجر بعد.</p>}</section> : null}</section>;
}

function OfferEditor({ offer, products, storeId, saving, deleting, onUpdate, onRemove, onPreview }: { offer: PartnerOffer; products: PartnerProduct[]; storeId: number; saving: boolean; deleting: boolean; onUpdate: (input: { id: number; storeId: number; catalogItemId: number; text: string; imageUrl: string; imageStorageKey: string; durationDays: number; offerPrice: number; active: boolean }) => void; onRemove: (id: number) => void; onPreview: (src: string, alt: string) => void }) {
  const [text, setText] = useState(offer.text);
  const [catalogItemId, setCatalogItemId] = useState(offer.catalogItemId ? String(offer.catalogItemId) : "");
  const [durationDays, setDurationDays] = useState(String(offer.durationDays ?? 30));
  const [offerPrice, setOfferPrice] = useState(String(toNewSyp(offer.offerPrice)));
  const [active, setActive] = useState(offer.active);
  const selectedProduct = products.find(product => String(product.id) === catalogItemId) ?? null;
  const originalPriceNew = selectedProduct ? toNewSyp(selectedProduct.unitPrice) : 0;
  const offerPriceNew = Number(offerPrice);
  const calculatedDiscount = originalPriceNew > 0 && offerPriceNew > 0 ? Math.round((originalPriceNew - offerPriceNew) * 100 / originalPriceNew) : 0;
  const validOfferPrice = Number.isInteger(offerPriceNew) && offerPriceNew > 0 && offerPriceNew < originalPriceNew && calculatedDiscount >= 1 && calculatedDiscount <= 90;
  const expiresAt = offer.expiresAt ? new Date(offer.expiresAt) : null;
  const expired = !offer.active || Boolean(expiresAt && expiresAt.getTime() <= Date.now());
  const daysRemaining = offerDaysRemaining(offer.expiresAt);
  return <article className="rounded-2xl border border-slate-200 p-3"><OfferArtworkPreview product={selectedProduct} storeName="لحظة" title={text || "عنوان العرض"} offerPrice={validOfferPrice ? toLegacySyp(offerPriceNew) : offer.offerPrice} customImage={offer.imageUrl || undefined} compact /><div className="mt-3 grid gap-3 sm:grid-cols-2"><div><Label>وصف العرض</Label><Textarea value={text} onChange={event => setText(event.target.value)} className="mt-1 min-h-20" /></div><div className="grid content-start gap-3"><div><Label>صنف العرض</Label><select value={catalogItemId} onChange={event => setCatalogItemId(event.target.value)} className="form-select mt-1"><option value="">اختر صنف العرض</option>{products.map(product => <option key={product.id} value={product.id}>{product.name} · {formatSyp(product.unitPrice)}</option>)}</select></div><div className="grid grid-cols-2 gap-2"><div><Label>سعر العرض</Label><Input inputMode="numeric" value={offerPrice} onChange={event => setOfferPrice(event.target.value.replace(/\D/g, ""))} className="mt-1 h-9" /><p className="mt-1 text-[0.65rem] font-bold text-[#63301b]">خصم محسوب: {calculatedDiscount || "—"}%</p></div><div><Label>المدة</Label><Input inputMode="numeric" value={durationDays} onChange={event => setDurationDays(event.target.value.replace(/\D/g, ""))} className="mt-1 h-9" /></div></div></div></div><div className={`mt-3 rounded-xl px-3 py-2 text-xs font-bold ${expired ? "bg-red-50 text-red-700" : "bg-emerald-50 text-emerald-700"}`}>{expired ? "منتهي — أُزيل من واجهة العملاء" : daysRemaining !== null ? <><span>متبقٍ: {daysRemaining} {daysRemaining === 1 ? "يوم" : "أيام"}</span>{expiresAt ? <span className="mr-2 font-medium text-slate-500">· ينتهي في {expiresAt.toLocaleDateString("ar-SY", { year: "numeric", month: "long", day: "numeric" })}</span> : null}</> : "عرض قديم بلا مدة؛ حدّثه قبل طلب تمييزه."}</div><div className="mt-3 flex flex-wrap gap-2"><button onClick={() => setActive(value => !value)} className={`rounded-lg px-3 py-2 text-xs font-bold ${active ? "bg-emerald-50 text-emerald-700" : "bg-slate-100 text-slate-500"}`}>{active ? "العرض نشط" : "العرض موقوف"}</button><button disabled={saving || !catalogItemId || text.trim().length < 3 || Number(durationDays) < 1 || Number(durationDays) > 365 || !validOfferPrice} onClick={() => onUpdate({ id: offer.id, storeId, catalogItemId: Number(catalogItemId), text: text.trim(), imageUrl: offer.imageUrl ?? "", imageStorageKey: offer.imageStorageKey ?? "", durationDays: Number(durationDays), offerPrice: offerPriceNew, active })} className="rounded-lg bg-rose-50 px-3 py-2 text-xs font-bold text-[#63301b]">حفظ البطاقة</button><button disabled={deleting} onClick={() => onRemove(offer.id)} className="mr-auto rounded-lg bg-red-50 px-3 py-2 text-red-600"><Trash2 className="h-4 w-4" /></button></div></article>;
}

function OfferArtworkPreview({ product, storeName, title, offerPrice, customImage, compact = false }: { product: PartnerProduct | null; storeName: string; title: string; offerPrice?: number; customImage?: string; compact?: boolean }) {
  const originalPrice = product?.unitPrice ?? 0;
  const finalPrice = offerPrice && offerPrice > 0 ? offerPrice : 0;
  const discountPercent = originalPrice > 0 && finalPrice > 0 ? Math.round((originalPrice - finalPrice) * 100 / originalPrice) : 0;
  const image = customImage || product?.imageUrl || "";
  return <article className={`lahza-offer-artwork ${compact ? "lahza-offer-artwork-compact" : ""}`}><div className="lahza-offer-artwork-glow" /><span className="lahza-offer-artwork-brand">لحظة</span><span className="lahza-offer-artwork-badge">خصم {discountPercent || "—"}%</span><div className="lahza-offer-artwork-copy"><small>{storeName}</small><strong>{title}</strong>{product ? <span>{product.name}</span> : <span>اختر المنتج لتظهر صورته وسعره</span>}<div className="lahza-offer-artwork-prices">{originalPrice > 0 ? <span className="lahza-offer-price-old"><i>قبل العرض</i><del>{formatSyp(originalPrice)}</del></span> : null}{finalPrice > 0 ? <span className="lahza-offer-price-new"><i>فقط</i><b>{formatSyp(finalPrice)}</b></span> : null}</div></div><div className="lahza-offer-artwork-product">{image ? <><img src={image} alt={product?.name ?? "صورة العرض"} /><span className="lahza-offer-phosphor-layer" aria-hidden="true" /></> : <ImageIcon className="h-12 w-12" />}</div></article>;
}

function ImageThumbnail({ src, alt, onPreview }: { src?: string | null; alt: string; onPreview: (src: string, alt: string) => void }) {
  if (!src) return <span className="grid h-[76px] w-[76px] shrink-0 place-items-center rounded-xl bg-slate-100 text-slate-400"><ImageIcon className="h-5 w-5" /></span>;
  return <button type="button" onClick={() => onPreview(src, alt)} className="h-[76px] w-[76px] shrink-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm transition hover:scale-105 focus:outline-none focus:ring-2 focus:ring-[#e95e2a]" title="تكبير الصورة"><img src={src} alt={alt} className="h-full w-full object-cover" /></button>;
}

function FeaturedOffersPanel({ offers, submitting, onRequest }: { offers: PartnerOffer[]; submitting: boolean; onRequest: (offer: PartnerOffer) => void }) {
  const eligibleOffers = offers.filter(offer => offer.active && offer.featuredStatus !== "none" && (!offer.expiresAt || new Date(offer.expiresAt).getTime() > Date.now()));
  const statusCopy: Record<PartnerOffer["featuredStatus"], { label: string; className: string }> = {
    none: { label: "غير مطلوب بعد", className: "bg-slate-100 text-slate-600" },
    pending: { label: "بانتظار موافقة المالك", className: "bg-amber-100 text-amber-900" },
    approved: { label: "معتمد ويظهر في الواجهة", className: "bg-emerald-100 text-emerald-800" },
    rejected: { label: "لم يُعتمد بعد", className: "bg-red-100 text-red-700" },
  };
  return <section className="space-y-5"><section className="rounded-3xl border border-amber-200 bg-gradient-to-l from-amber-50 to-white p-5"><div className="flex items-start gap-3"><span className="grid h-11 w-11 place-items-center rounded-2xl bg-amber-500 text-white"><BadgePercent className="h-5 w-5" /></span><div><h2 className="text-lg font-black text-[#4a2618]">العروض المميزة</h2><p className="mt-1 text-sm leading-6 text-slate-600">أنشئ العرض المميز من النموذج أعلاه وأرسله للمالك. بعد الاعتماد فقط يظهر في شريط العروض وصفحة العروض المميزة.</p></div></div></section>{eligibleOffers.length ? <div className="space-y-3">{eligibleOffers.map(offer => { const status = statusCopy[offer.featuredStatus]; return <article key={offer.id} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><div className="flex items-start gap-3">{offer.imageUrl ? <img src={offer.imageUrl} alt="" className="h-16 w-16 rounded-xl object-cover" /> : <span className="grid h-16 w-16 place-items-center rounded-xl bg-amber-50 text-amber-600"><BadgePercent className="h-5 w-5" /></span>}<div className="min-w-0 flex-1"><strong className="block text-base text-[#4a2618]">{offer.text}</strong><span className={`mt-2 inline-flex rounded-full px-3 py-1 text-xs font-bold ${status.className}`}>{status.label}</span>{offer.featuredStatus === "rejected" && offer.featuredReviewNote ? <p className="mt-2 text-xs leading-5 text-red-700">ملاحظة المالك: {offer.featuredReviewNote}</p> : null}</div></div>{offer.featuredStatus !== "pending" && offer.featuredStatus !== "approved" ? <Button disabled={submitting} onClick={() => onRequest(offer)} className="mt-4 rounded-xl bg-amber-500 text-white hover:bg-amber-600"><BadgePercent className="h-4 w-4" /> {offer.featuredStatus === "rejected" ? "إعادة طلب التمييز" : "طلب عرض مميز"}</Button> : null}</article>; })}</div> : <section className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><BadgePercent className="mx-auto h-8 w-8 text-slate-400" /><strong className="mt-3 block text-[#4a2618]">لا توجد عروض مميزة قيد المراجعة أو معتمدة</strong><p className="mt-2 text-sm text-slate-500">استخدم النموذج أعلاه لإنشاء عرض مميز جديد وإرساله إلى المالك.</p></section>}</section>;
}

function WorkReportPanel({ report, loading, error }: { report?: WorkReport; loading: boolean; error?: string }) {
  if (loading) return <section className="rounded-3xl bg-white p-8"><Loading text="جارٍ إعداد تقرير العمل..." /></section>;
  if (error) return <section className="rounded-3xl border border-red-200 bg-red-50 p-6 text-sm font-bold text-red-700">تعذر تحميل التقرير: {error}</section>;
  if (!report) return <section className="rounded-3xl bg-white p-8 text-center text-sm text-slate-500">لا تتوفر بيانات تقرير العمل حالياً.</section>;
  const period = `${new Date(report.periodStart).toLocaleDateString("ar-SY")} — ${new Date(report.periodEnd).toLocaleDateString("ar-SY")}`;
  const cards = [{ label: "الطلبات", value: report.current.orders }, { label: "المكتملة", value: report.current.completed }, { label: "الملغاة/المرفوضة", value: report.current.cancelled }, { label: "المبيعات", value: `${report.current.sales} ل.س` }, { label: "زيارات المتجر", value: report.visits }, { label: "زيارات QR", value: report.qrVisits }];
  return <section className="space-y-4"><section className="rounded-3xl bg-gradient-to-l from-[#4a2618] to-[#7a3b1d] p-5 text-white"><div className="flex items-center gap-3"><FileText className="h-7 w-7" /><div><h2 className="text-xl font-black">تقرير العمل</h2><p className="mt-1 text-xs text-rose-100">ملخص متجرك خلال {period}</p></div></div><p className="mt-3 text-sm text-rose-100">الأرقام تخص المتجر أو المتاجر المرتبطة بحسابك فقط.</p></section><div className="grid grid-cols-2 gap-3 sm:grid-cols-3">{cards.map(card => <article key={card.label} className="rounded-2xl border border-slate-200 bg-white p-4 shadow-sm"><p className="text-xs font-bold text-slate-500">{card.label}</p><strong className="mt-2 block text-xl font-black text-[#4a2618]">{card.value}</strong></article>)}</div><section className="rounded-3xl border border-slate-200 bg-white p-5"><h3 className="font-black text-[#4a2618]">المنتجات الأكثر طلباً</h3>{report.current.topProducts.length ? <div className="mt-3 space-y-2">{report.current.topProducts.map(product => <div key={product.name} className="flex items-center justify-between rounded-xl bg-slate-50 px-3 py-2 text-sm"><span className="font-bold text-slate-700">{product.name}</span><span className="font-black text-[#63301b]">{product.quantity}</span></div>)}</div> : <p className="mt-3 text-sm text-slate-500">لا توجد طلبات منتجات خلال هذه الفترة.</p>}</section><section className="rounded-3xl border border-rose-100 bg-rose-50 p-4 text-sm text-[#4a2618]">مقارنة بالأسبوع السابق: {report.current.orders - report.previous.orders >= 0 ? "+" : ""}{report.current.orders - report.previous.orders} طلب، و{report.current.sales - report.previous.sales >= 0 ? "+" : ""}{report.current.sales - report.previous.sales} ل.س في المبيعات.</section></section>;
}
function ImagePreview({ preview, onClose }: { preview: { src: string; alt: string } | null; onClose: () => void }) {
  return <Dialog open={Boolean(preview)} onOpenChange={open => { if (!open) onClose(); }}><DialogContent dir="rtl" className="max-w-3xl rounded-3xl border-0 bg-slate-950 p-3 text-white"><DialogHeader><DialogTitle className="sr-only">تكبير الصورة</DialogTitle></DialogHeader>{preview ? <><button type="button" onClick={onClose} className="absolute left-4 top-4 z-10 grid h-10 w-10 place-items-center rounded-full bg-white/15 text-white backdrop-blur hover:bg-white/25"><X className="h-5 w-5" /></button><img src={preview.src} alt={preview.alt} className="mx-auto max-h-[75vh] max-w-full rounded-2xl object-contain" /></> : null}</DialogContent></Dialog>;
}

function TabButton({ active, danger, icon, children, onClick }: { active: boolean; danger?: boolean; icon: React.ReactNode; children: React.ReactNode; onClick: () => void }) { return <button onClick={onClick} className={`flex items-center justify-center gap-2 rounded-2xl px-4 py-3 text-sm font-black transition ${active ? danger ? "bg-red-600 text-white" : "bg-[#4a2618] text-white" : "bg-slate-50 text-slate-500"}`}>{icon}{children}</button>; }
function EmptyStores() { return <section className="rounded-3xl border border-dashed border-slate-200 bg-white p-8 text-center"><Store className="mx-auto h-8 w-8 text-slate-400" /><h2 className="mt-3 text-lg font-black text-[#4a2618]">لم يُعيّن لك متجر بعد</h2><p className="mt-2 text-sm leading-7 text-slate-500">تواصل مع مالك لحظة ليحدد لك المتجر الذي ستدير منتجاته.</p></section>; }
function Loading({ text }: { text: string }) { return <p dir="rtl" className="mt-4 flex items-center justify-center gap-2 text-sm text-slate-500"><Loader2 className="h-4 w-4 animate-spin" />{text}</p>; }
